const SCH=(()=>{const T=x=>{const m=/(\d+):(\d+)\s*(AM|PM)/i.exec(x||"");if(!m)return 9999;let h=+m[1]%12;if(/pm/i.test(m[3]))h+=12;return h*60+ +m[2]};
 const days={1:[],2:[],3:[]};
 days[1].push({t:"9:00 AM",n:"Inauguration",s:"Lamp lighting and welcome",dur:60});
 days[3].push({t:"6:00 PM",n:"Live concert",s:"Rajesh Krishnan performs live · closing",dur:120});
 CATS.forEach(c=>c.ev.forEach(e=>{if(!e.d||!e.tm)return;const st=(/\d+:\d+\s*[AP]M/i.exec(e.tm)||[e.tm])[0].trim();
  (e.d.split("Nov")[0].match(/\d+/g)||[]).forEach(n=>{const k=+n-3;if(days[k])days[k].push({t:st,n:e.n,c:c.n,tm:e.tm,v:e.v,s:[e.tm,e.v].filter(Boolean).join(" · ")})})}));
 const out={};for(const k in days){const g={};days[k].forEach(x=>(g[x.t]=g[x.t]||[]).push(x));out[k]=Object.keys(g).sort((a,b)=>T(a)-T(b)).map(t=>[t,g[t]])}return out})();
