const spCard=([src,alt,cap,bc],i)=>`<span class="sp${cap?" sp-cap":""}" style="--bc:${bc};--sd:${(i*1.5)%6}s"><img src="${src}" alt="${alt}">${cap?`<em>${cap}</em>`:""}</span>`;
const spSet=[...SP,...SP,...SP,...SP].map(spCard).join("");
$("#t1").innerHTML=spSet+spSet.replace(/<span class="sp/g,'<span aria-hidden="true" class="sp');

const flat=CATS.flatMap(c=>c.ev);
$("#cats").innerHTML=CATS.map((c,i)=>`<div class="rv ${['l','','r'][i%3]}" style="--d:${i*.12}s"><button class="cat" data-cat="${i}" style="--cc:${CC[i]||""}" aria-expanded="false" aria-controls="subwrap">${ico(c.ic)}<h3>${c.n}</h3><span class="n">${c.ev.length} event${c.ev.length===1?"":"s"}</span><span class="hint"><b class="hint-t" data-m="Click to open" data-t="Tap to open" data-mc="Click to close" data-tc="Tap to close"></b><span class="chev">${ico('chev')}</span></span></button></div>`).join("");
let openC=-1;
const evMeta=e=>{const m=[["Date",e.d],["Time",e.tm],["Team",e.t],["Venue",e.v]].filter(x=>x[1]);return m.length?`<div class="evdt">${m.map(x=>`<div><i>${x[0]}</i><b>${x[1]}</b></div>`).join("")}</div>`:""};
const evCard=(i,k,n)=>{const e=CATS[i].ev[k];return `<div class="sub" style="--i:${n??k};--cc:${CC[i]||""}">${e.g?`<small>${e.g.toUpperCase()}</small>`:""}<h4>${e.n}</h4>${e.f?`<div class="feetag">Entry fee ${e.f[0]} <span>${e.f[1]}</span></div>`:""}${PRIZES[e.n]?`<div class="prizetag">Win ${PRIZES[e.n]}</div>`:""}${evMeta(e)}<div class="row"><a class="btn" href="#" data-reg data-ev="${e.n}">Register</a><button class="btn alt" data-det="${i}-${k}">Details</button></div></div>`};
const catHTML=i=>{const c=CATS[i];return `<div class="subhead" style="--cc:${CC[i]||""}">${c.n} events</div><div class="subs">`+c.ev.map((e,k)=>evCard(i,k)).join("")+"</div>"};
function openAll(){if(typeof resetFlt==="function")resetFlt();$$(".cat").forEach(b=>b.setAttribute("aria-expanded","true"));openC=-2;$("#subs").innerHTML=CATS.map((c,i)=>catHTML(i)).join("");applyForm();$("#subwrap").classList.add("open")}
const mb=$("#more"),nv=$("#nav");
function menu(o){nv.classList.toggle("open",o);$("#scrim").classList.toggle("open",o);mb.setAttribute("aria-expanded",String(o))}
mb.addEventListener("click",e=>{e.stopPropagation();menu(!nv.classList.contains("open"))});
function applyForm(){$$(".feetag,.fee").forEach(f=>{f.tabIndex=0;f.setAttribute("role","link");f.title="Tap to register"});$$("a[data-reg]").forEach(a=>{const u=GFORMS[a.dataset.ev];if(u){a.href=u;a.target="_blank";a.rel="noopener"}else if(!a.dataset.ev){a.href="#events"}})}
function openCat(i){const w=$("#subwrap");if(typeof resetFlt==="function")resetFlt();$$(".cat").forEach(b=>b.setAttribute("aria-expanded",String(+b.dataset.cat===i&&openC!==i)));
 if(openC===i){w.classList.remove("open");openC=-1;return}
 openC=i;const c=CATS[i];
 $("#subs").innerHTML=catHTML(i);
 applyForm();w.classList.add("open");setTimeout(()=>$("#subs").scrollIntoView({behavior:"smooth",block:"center"}),450)}

