function RM(){return matchMedia("(prefers-reduced-motion:reduce)").matches}
function TM(x){const m=/(\d+):(\d+)\s*(AM|PM)/i.exec(x||"");if(!m)return 9999;let h=+m[1]%12;if(/pm/i.test(m[3]))h+=12;return h*60+ +m[2]}
function win(x,all){const r=/(\d+:\d+\s*[AP]M)\s*[–-]\s*(\d+:\d+\s*[AP]M)/i.exec(x.tm||"");const st=TM(x.t);if(r)return [st,TM(r[2])];if(/onwards/i.test(x.tm||"")&&all){const nx=all.filter(y=>y!==x&&y.v&&y.v===x.v&&TM(y.t)>st).map(y=>TM(y.t)).sort((a,b)=>a-b)[0];return [st,nx||17*60]}return [st,st+(x.dur||120)]}
